@_mutmut_mutated(mutants_x__derive_key_v2__mutmut)
def _derive_key_v2(jwt_secret: str, salt: bytes) -> bytes:
    """v2 KDF using scrypt with a random per-credential salt."""
    raw = hashlib.scrypt(
        jwt_secret.encode(),
        salt=salt,
        n=2**14,
        r=8,
        p=1,
        maxmem=64 * 1024 * 1024,
        dklen=32,
    )
    return base64.urlsafe_b64encode(raw)


