    secret = decrypt_credential(user.alpaca_secret_enc) if user.alpaca_secret_enc else ""
    if not key or (broker_type != "ibkr" and not secret):
        log.warning("broker_svc: user=%d — credential decryption failed, skipping", user.id)
        return

