    notional = round(base_notional * scale, 2)
    notional = max(notional, 1.0)  # minimum

    ticker = sig.get("ticker", "")
    action = sig.get("action", "")
    if action not in ("BUY", "SELL"):
        return

    side = "buy" if action == "BUY" else "sell"

