                result = await client_rest.submit_bracket_stop_order(
                    key,
                    secret,
                    symbol=ticker,
                    notional=notional,
                    side=side,
                    stop_price=float(stop_price),
                    take_profit_price=float(target_price) if target_price else None,
                    entry_price=float(entry_price) if entry_price else None,
                    live=live,
                )
